typedef struct { int pin; void (*handler)(void*); void* arg; } gpio_isr_t;

void gpio_isr_disable(int pin) { (void)pin; }
void gpio_release_observer(gpio_isr_t* isr) { (void)isr; }
void gpio_destroy_endpoint(gpio_isr_t* isr) { (void)isr; }
void gpio_free_isr(gpio_isr_t* isr) { (void)isr; }

void gpio_isr_handler_remove(gpio_isr_t* isr)
{
  gpio_release_observer(isr);
  gpio_isr_disable(isr->pin);
  gpio_destroy_endpoint(isr);
  gpio_free_isr(isr);
}

void gpio_isr_handler_remove_variant(gpio_isr_t* isr)
{
  gpio_release_observer(isr);
  gpio_isr_disable(isr->pin);
  gpio_destroy_endpoint(isr);
  gpio_free_isr(isr);
}

void gpio_isr_handler_remove_neighbor(gpio_isr_t* isr)
{
  gpio_release_observer(isr);
  gpio_destroy_endpoint(isr);
  gpio_free_isr(isr);
}
